// 回归测试: 后端 LSP completion item 的 sortText 必须原样映射到 Monaco 补全项的 sortText。
// monaco.ts 顶层依赖 worker / Tauri / DOM, 无法在 node 测试里 import,
// 因此直接测纯转换模块 completion.ts (kind / range / snippet 常量由测试注入)。

import type * as monaco from 'monaco-editor';
import { describe, expect, it } from 'vitest';

import type { LspCompletionItem } from './client';
import { toCompletionItem, type CompletionConversionDeps } from './completion';

const deps: CompletionConversionDeps = {
  kinds: { 14: 14 as monaco.languages.CompletionItemKind },
  textKind: 0 as monaco.languages.CompletionItemKind,
  insertAsSnippet: 1 as monaco.languages.CompletionItemInsertTextRule,
  toRange: (range) => ({
    startLineNumber: range.start.line + 1,
    startColumn: range.start.character + 1,
    endLineNumber: range.end.line + 1,
    endColumn: range.end.character + 1,
  }),
};

const fallbackRange: monaco.IRange = {
  startLineNumber: 1,
  startColumn: 1,
  endLineNumber: 1,
  endColumn: 1,
};

describe('toCompletionItem', () => {
  it('把后端 completion item 的 sortText 原样映射到 Monaco 结果', () => {
    const backendItem: LspCompletionItem = { label: 'keyword', kind: 14, sortText: '0005' };

    const result = toCompletionItem(backendItem, fallbackRange, deps);

    expect(result.label).toBe('keyword');
    expect(result.insertText).toBe('keyword');
    expect(result.sortText).toBe('0005');
  });
});
